'use strict';

const ELEC275_D2_ORIGINAL=(()=>{
 const S=(title,math,why)=>({title,math,why});
 const O=o=>({lane:'original',difficulty:o.difficulty||(o.kind==='long'?'Exam':'Core'),time:o.time||(o.kind==='long'?18:o.kind==='mcq'?3:7),calculator:o.calculator||'Scientific calculator optional',assumptions:o.assumptions||'DC steady state; ideal wires and sources unless stated otherwise. Use every reference direction defined in the question.',reviewStatus:'reviewed',...o});
 return [
O({id:'MCQ-01',kind:'mcq',difficulty:'Guided',topic:'Method selection',title:'Count unknowns before choosing a method',prompt:'A planar resistive circuit has five non-reference nodes and three meshes. Two ideal voltage sources each connect a non-reference node directly to ground. With no current sources, which nodal formulation is sufficient?',options:['Five free node voltages','Three free node voltages','Two free node voltages','One free node voltage'],correctIndex:1,optionFeedback:['Five ignores the two independent ground-source constraints.','Correct: five minus two source-fixed nodes leaves three free node voltages.','Two would require three independent ground-source constraints, but only two exist.','One would require four independent constraints, but only two exist.'],givens:'Five non-reference nodes; two are fixed independently by grounded voltage sources.',unknowns:'Minimum number of free nodal unknowns.',answer:'3 free node voltages.',readAloud:'Count every non-reference node, then subtract nodes whose potentials are fixed directly relative to ground. The remaining nodes need KCL equations.',symbols:'Nfree=Nnonref−Nfixed is the number of independent node-voltage unknowns.',steps:[S('Start with all node candidates','N_{nonref}=5','Each separate conducting region initially receives one potential variable.'),S('Apply grounded-source constraints','N_{free}=5-2=3','Each grounded ideal voltage source determines one node potential absolutely.')],verification:'Three KCL equations plus the two known source potentials determine all five original node voltages.',trap:'Do not subtract floating voltage sources in the same way; those require supernodes.',fastCheck:'Cross out each ground-fixed node and count what remains.'}),
O({id:'MCQ-02',kind:'mcq',difficulty:'Guided',topic:'Supernodes',title:'Choose the currents crossing a supernode boundary',prompt:'Nodes A and B are joined by a 3 V source. External resistors connect A to ground through 2 Ω and B to ground through 6 Ω. No other elements connect to A or B. Which supernode equation is correct?',options:['A/2+B/6=0','A/2−B/6=3','(A−B)/3=0','A/2+B/6=3'],correctIndex:0,optionFeedback:['Correct: only the two external resistor currents cross the supernode boundary.','The source voltage does not inject 3 A into the enclosure.','Ohm’s law cannot be applied through the ideal voltage source.','The 3 V value is a voltage constraint, not a 3 A source current.'],givens:'A−B=3 V; external shunts are 2 Ω at A and 6 Ω at B.',unknowns:'Correct KCL equation for the A–B supernode.',answer:'A/2+B/6=0, together with A−B=3 V.',readAloud:'The source current stays inside the supernode and cancels. Add only currents leaving through external resistors, then append the source-voltage constraint.',symbols:'A,B are node voltages; currents leaving are A/2 and B/6 amperes.',steps:[S('Enclose both source terminals','I_{external}=A/2+B/6','Internal source current does not cross the chosen boundary.'),S('Balance and append the constraint','A/2+B/6=0,\\qquad A-B=3','KCL and the independent source relation together determine both voltages.')],verification:'Solving A−B=3 V and A/2+B/6=0 gives A=0.75 V and B=−2.25 V; the shunt currents are 0.375 A and −0.375 A, which sum to zero.',trap:'The 3 V source is not a 3 A injection and its current is unknown until KCL is solved.',fastCheck:'Circle the source; count only resistor branches crossing the circle.'}),
O({id:'MCQ-03',kind:'mcq',difficulty:'Guided',topic:'Mesh analysis',title:'Outer current source fixes one mesh current',prompt:'A 2 A current source lies only on the outer left branch of clockwise mesh 1. The clockwise reference travels upward on that branch, matching the source. What is the constraint?',options:['i1=−2 A','i1−i2=2 A','i1=2 A','i1+i2=2 A'],correctIndex:2,optionFeedback:['The negative sign would apply if the mesh reference opposed the source.','A difference is used for a source shared with mesh 2, not an outer branch.','Correct: the entire outer-branch current is the mesh-1 current.','No adjacent mesh shares this branch, so i2 does not enter.'],givens:'Outer branch; 2 A upward; clockwise i1 also upward there.',unknowns:'Current-source constraint.',answer:'i1=2 A.',readAloud:'When no second mesh shares the branch, the source current equals the single mesh current with a sign chosen by direction agreement.',symbols:'i1 is clockwise mesh-1 current; iS=2 A is the outer-branch source current.',steps:[S('Check branch ownership','N_{meshes\\ on\\ branch}=1','Only mesh 1 uses the outer branch.'),S('Compare directions and write equality','i_1=i_S=2\\ \\mathrm{A}','Matching upward directions give a positive constraint.')],verification:'Substituting i1=2 A reproduces exactly 2 A upward on the physical branch.',trap:'Do not build a supermesh when the current source is not shared.',fastCheck:'One mesh means one current; two meshes means a difference.'}),
O({id:'MCQ-04',kind:'mcq',difficulty:'Guided',topic:'Supermeshes',title:'Shared current source gives a current difference',prompt:'A 4 A source points upward between clockwise meshes 2 and 3. Mesh 2 travels downward on the shared branch; mesh 3 travels upward. Which constraint is correct?',options:['i2−i3=4 A','i3−i2=4 A','i2+i3=4 A','i3=4 A'],correctIndex:1,optionFeedback:['This is the negative of the physical upward branch current.','Correct: upward i3 minus downward i2 equals the 4 A upward source.','Mesh currents oppose on the shared branch, so they subtract rather than add.','The source is shared, so it does not fix i3 alone.'],givens:'Shared branch; source 4 A upward; i2 downward and i3 upward there.',unknowns:'Signed mesh-current constraint.',answer:'i3−i2=4 A.',readAloud:'Net upward current is the upward mesh contribution minus the downward mesh contribution. Set that net current equal to the source.',symbols:'i2,i3 are clockwise mesh currents; positive branch current is defined upward.',steps:[S('Resolve branch directions','I_{up}=i_3-i_2','Each mesh current retains its own sign in this expression.'),S('Apply the source value','i_3-i_2=4\\ \\mathrm{A}','The difference replaces one KVL equation around the two meshes.')],verification:'If i3=5 A and i2=1 A, physical upward current is 4 A, matching the source.',trap:'Setting either mesh current equal to 4 A discards the other mesh contribution.',fastCheck:'Write up equals up-minus-down before inserting numbers.'}),
O({id:'MCQ-05',kind:'mcq',difficulty:'Core',topic:'Nodal analysis',title:'Solve one source-fed node',prompt:'A 12 V source feeds node A through 6 Ω. A 4 Ω resistor connects A to ground. What is VA?',options:['2 V','4 V','6 V','8 V'],correctIndex:3,optionFeedback:['Two volts would make the source-feed current too large for KCL.','Four volts is one third of the source, not the loaded divider result.','Six volts treats the two equal-looking digits as equal resistances; they are not.','Correct: VA=12×4/(6+4)=8 V.'],givens:'VS=12 V; series R1=6 Ω; shunt R2=4 Ω.',unknowns:'Node voltage VA.',answer:'VA=8 V.',readAloud:'The source-feed resistor and shunt form a series path to ground. Divide twelve volts by ten ohms, then multiply the current by four ohms.',symbols:'I is loop current; VA=IR2 is the shunt voltage.',steps:[S('Combine the series resistances','R_{eq}=6+4=10\\ \\Omega','The same source current crosses both resistors.'),S('Find current and node voltage','I=12/10=1.2\\ \\mathrm{A},\\qquad V_A=1.2(4)=8\\ \\mathrm{V}','VA is the drop across the 4 Ω shunt.')],verification:'The 6 Ω drop is 1.2×6=4 V, and 4+8=12 V.',trap:'VA is not 12 V because the series resistor carries current.',fastCheck:'Four tenths of twelve volts is eight volts.'}),
O({id:'MCQ-06',kind:'mcq',difficulty:'Core',topic:'Supernodes',title:'Solve a two-resistor supernode',prompt:'Nodes A and B satisfy B=A+3 V. A connects to ground through 2 Ω and B through 6 Ω. No other external connections exist. What are A and B?',options:['A=0.75 V,B=3.75 V','A=−0.75 V,B=2.25 V','A=0.75 V,B=−2.25 V','A=3 V,B=0 V'],correctIndex:1,optionFeedback:['These values satisfy neither B=A+3 nor the resistor-current balance.','Correct: 3A+B=0 and B=A+3 give A=−0.75 V and B=2.25 V.','These values satisfy B=A−3, which reverses the stated source constraint.','This assigns the entire source voltage to A without solving KCL.'],givens:'B−A=3 V; shunts 2 Ω and 6 Ω.',unknowns:'Both node voltages.',answer:'A=−0.75 V and B=2.25 V.',readAloud:'The supernode balance is A over two plus B over six equals zero. Multiply by six and substitute B equals A plus three.',symbols:'A,B are node voltages; B−A=3 V is the source constraint.',steps:[S('Write and scale supernode KCL','A/2+B/6=0\\Rightarrow3A+B=0','Only the two shunt currents leave the supernode.'),S('Substitute the source relation','3A+A+3=0\\Rightarrow A=-0.75\\ \\mathrm{V},\\quad B=2.25\\ \\mathrm{V}','Substitution gives 4A=−3, so A=−0.75 V; adding 3 V then gives B=2.25 V.')],verification:'Using the solved values,3(−0.75)+2.25=0 and B−A=3 V.',trap:'A supernode fixes a voltage difference, not either node to zero.',fastCheck:'Check the difference first, then the shunt-current sum.'}),
O({id:'MCQ-07',kind:'mcq',difficulty:'Core',topic:'Mesh analysis',title:'Solve two coupled mesh equations',prompt:'Two clockwise meshes obey 6i1−2i2=12 and −2i1+4i2=0. What is the shared-branch current i1−i2?',options:['0.6 A','1.2 A','2.4 A','3.6 A'],correctIndex:1,optionFeedback:['This is half the correct shared current and does not satisfy the equations.','Correct: i1=2.4 A and i2=1.2 A, so their difference is 1.2 A.','This is i1 alone, not the shared-branch current.','This adds the mesh currents rather than subtracting them.'],givens:'Two mesh KVL equations with a 2 Ω shared branch.',unknowns:'Signed shared-branch current i1−i2.',answer:'i1−i2=1.2 A.',readAloud:'The second equation says i two equals one half i one. Substitute into the first, then subtract the two mesh currents.',symbols:'i1,i2 are clockwise mesh currents; the shared reference follows i1.',steps:[S('Eliminate i2','i_2=i_1/2\\Rightarrow6i_1-i_1=12\\Rightarrow i_1=2.4\\ \\mathrm{A}','Substitution reduces the coupled system to one equation.'),S('Recover the branch difference','i_2=1.2\\ \\mathrm{A},\\qquad i_1-i_2=1.2\\ \\mathrm{A}','A shared branch carries a difference, not i1 alone.')],verification:'6(2.4)−2(1.2)=12 V and −2(2.4)+4(1.2)=0 V.',trap:'Do not report 2.4 A merely because it is the first mesh current.',fastCheck:'The second mesh is half the first; their difference is also half.'}),
O({id:'MCQ-08',kind:'mcq',difficulty:'Core',topic:'Dependent sources',title:'Translate a dependent-source constraint',prompt:'A dependent voltage source between nodes A and B has value 4vx, with its positive terminal at A. The controlling voltage vx is the potential of node C to ground. Which equation must accompany KCL?',options:['A+B=4C','A−B=4C','B−A=4C','A−B=4/C'],correctIndex:1,optionFeedback:['A sum does not represent the potential drop from A to B.','Correct: positive at A means A−B equals the source value 4vx=4C.','This reverses the marked source polarity.','Division by C is not the linear controlling relation stated.'],givens:'Source value 4vx; positive terminal A; vx=C.',unknowns:'Dependent voltage-source constraint.',answer:'A−B=4C.',readAloud:'Voltage at the positive terminal minus voltage at the negative terminal equals the source value. Replace v x with C.',symbols:'A,B,C are node potentials; the source gain is 4 with appropriate units.',steps:[S('Read the terminal polarity','V_+-V_-=A-B','The plus and minus labels determine the subtraction order.'),S('Substitute source and control','A-B=4v_x=4C','The controlling relation remains active during the solve.')],verification:'At any solution, the potential drop A−B is exactly four times the controlling node potential C.',trap:'Do not treat 4vx as a fixed independent voltage.',fastCheck:'Plus minus minus, then replace the control variable.'}),
O({id:'MCQ-09',kind:'mcq',difficulty:'Core',topic:'Source transformation',title:'Convert a Thévenin branch to Norton form',prompt:'A 24 V ideal voltage source is in series with 6 Ω. Which Norton equivalent has the same terminal behavior?',options:['4 A in parallel with 6 Ω','24 A in parallel with 6 Ω','4 A in series with 6 Ω','144 A in parallel with 24 Ω'],correctIndex:0,optionFeedback:['Correct: IN=24/6=4 A and RN remains 6 Ω in parallel.','This multiplies rather than divides and gives the wrong current unit scale.','A Norton source is parallel, not series, with its resistance.','This changes both values without preserving V/R or terminal resistance.'],givens:'VTh=24 V; series resistance R=6 Ω.',unknowns:'Norton current and resistance.',answer:'IN=4 A in parallel with RN=6 Ω.',readAloud:'Norton current equals Thévenin voltage divided by series resistance. The same six-ohm resistance moves from series to parallel.',symbols:'IN=VTh/R; RN=RTh.',steps:[S('Compute short-circuit current','I_N=24/6=4\\ \\mathrm{A}','Shorting the terminals leaves only the 6 Ω resistor around the source.'),S('Retain terminal resistance','R_N=6\\ \\Omega','Deactivating the voltage source leaves 6 Ω between the terminals.')],verification:'The Norton open-circuit voltage is INRN=4×6=24 V, matching the original.',trap:'Do not change resistance value or leave it in series after conversion.',fastCheck:'Check INRN returns 24 V.'}),
O({id:'MCQ-10',kind:'mcq',difficulty:'Core',topic:'Norton equivalents',title:'Combine parallel Norton sources and resistances',prompt:'A 3 A upward source parallels a 1 A downward source. Resistors 6 Ω and 3 Ω also share the same two nodes. What is the combined Norton equivalent?',options:['4 A upward with 9 Ω','2 A upward with 2 Ω','2 A downward with 2 Ω','2 A upward with 9 Ω'],correctIndex:1,optionFeedback:['Opposing currents subtract, and parallel resistances do not add.','Correct: net current is 2 A upward and 6∥3=2 Ω.','The 3 A source dominates, so net current is upward.','Parallel resistance is 2 Ω, not the series sum 9 Ω.'],givens:'Source currents +3 A and −1 A upward; parallel R1=6 Ω,R2=3 Ω.',unknowns:'Single Norton current and resistance.',answer:'IN=2 A upward and RN=2 Ω.',readAloud:'Signed parallel source currents add. Parallel conductances add, so equivalent resistance is the reciprocal of one sixth plus one third.',symbols:'IN=3−1; 1/RN=1/6+1/3 siemens.',steps:[S('Add signed source currents','I_N=3-1=2\\ \\mathrm{A}\\ \\text{upward}','The downward source enters with a negative sign.'),S('Add conductances','1/R_N=1/6+1/3=1/2\\ \\mathrm{S}\\Rightarrow R_N=2\\ \\Omega','Parallel resistors combine through conductance, not direct addition.')],verification:'Open-circuit voltage is 2×2=4 V; the original net 2 A through 6∥3 also gives 4 V.',trap:'Resistances in parallel never add as 6+3 Ω.',fastCheck:'Net current two amps; small parallel resistor two ohms.'}),
O({id:'MCQ-11',kind:'mcq',difficulty:'Core',topic:'Equivalent resistance',title:'Reduce a series-parallel ladder',prompt:'A 4 Ω resistor is in series with a parallel pair of 6 Ω and 3 Ω. What is the input resistance?',options:['2 Ω','6 Ω','9 Ω','13 Ω'],correctIndex:1,optionFeedback:['Two ohms is only the parallel pair and omits the series resistor.','Correct: 6∥3=2 Ω and 4+2=6 Ω.','Nine ohms adds 4+6+3 incorrectly as a mixed series-parallel network.','Thirteen ohms adds all resistances and adds the parallel result again.'],givens:'Series 4 Ω; downstream 6 Ω∥3 Ω.',unknowns:'Single input equivalent resistance.',answer:'Req=6 Ω.',readAloud:'Six ohms in parallel with three ohms gives two ohms. The input four-ohm resistor then adds in series.',symbols:'Rp=6∥3; Req=4+Rp.',steps:[S('Reduce the parallel pair','R_p=6\\parallel3=\\frac{6(3)}{6+3}=2\\ \\Omega','The pair shares both terminal nodes.'),S('Add the series input','R_{eq}=4+2=6\\ \\Omega','Every input current crosses the 4 Ω resistor before dividing.')],verification:'A 6 V test source produces 1 A, so R=V/I=6 Ω.',trap:'Only elements sharing both nodes can be combined in parallel.',fastCheck:'Parallel part two, plus series four, gives six.'}),
O({id:'MCQ-12',kind:'mcq',difficulty:'Core',topic:'Current division',title:'Use the other branch resistance',prompt:'A 5 A current divides between parallel 10 Ω and 15 Ω branches. How much current flows through the 10 Ω branch?',options:['2 A','2.5 A','3 A','5 A'],correctIndex:2,optionFeedback:['Two amperes is the current through the 15 Ω branch.','Equal splitting would require equal resistances.','Correct: I10=5×15/(10+15)=3 A.','The total divides, so the 10 Ω branch cannot carry all 5 A.'],givens:'IT=5 A; parallel branches 10 Ω and 15 Ω.',unknowns:'Current through the 10 Ω branch.',answer:'I10=3 A.',readAloud:'For two parallel branches, the current in one branch equals total current times the other branch resistance divided by their sum.',symbols:'I10 is branch current; common voltage V=10I10=15I15.',steps:[S('Apply two-branch current division','I_{10}=5\\frac{15}{10+15}=3\\ \\mathrm{A}','The smaller 10 Ω branch receives the larger current.'),S('Find the complementary current','I_{15}=5-3=2\\ \\mathrm{A}','KCL requires both branch currents to total 5 A.')],verification:'Common voltage is 10×3=30 V and also 15×2=30 V.',trap:'Do not put the target branch resistance in the two-branch numerator.',fastCheck:'Smaller resistor gets three fifths of the current.'}),
O({id:'MCQ-13',kind:'mcq',difficulty:'Exam',topic:'Superposition',title:'Add voltage-source and current-source responses',prompt:'Node A connects to a 10 V source through 5 Ω and to ground through 10 Ω. A 2 A source injects current upward into A. What is VA?',options:['20/3 V','10 V','40/3 V','20 V'],correctIndex:2,optionFeedback:['This is only the voltage-source contribution and omits the current source.','Ten volts assumes the source-feed resistor has no drop.','Correct: each source contributes 20/3 V, so total VA=40/3 V.','Twenty volts doubles the source voltage without the network ratio.'],givens:'10 V through 5 Ω; 10 Ω shunt; 2 A injected into A.',unknowns:'Total node voltage by superposition.',answer:'VA=40/3=13.3333 V.',readAloud:'With the current source open, voltage division gives twenty thirds. With the voltage source shorted, two amps enter five parallel ten ohms, again giving twenty thirds.',symbols:'VA′ is voltage-source response; VA″ is current-source response; VA=VA′+VA″.',steps:[S('Compute both independent responses','V_A\\prime=10\\frac{10}{5+10}=20/3\\ \\mathrm{V},\\qquad V_A\\prime\\prime=2(5\\parallel10)=20/3\\ \\mathrm{V}','Open the current source for the first case and short the voltage source for the second.'),S('Add signed components','V_A=20/3+20/3=40/3\\ \\mathrm{V}','Both contributions are positive at A under the selected polarity.')],verification:'Original KCL is (VA−10)/5+VA/10=2 A; substituting 40/3 V gives 2/3+4/3=2 A.',trap:'Short only the ideal voltage source, leaving its 5 Ω series resistor connected.',fastCheck:'Each contribution is six and two thirds volts.'}),
O({id:'MCQ-14',kind:'mcq',difficulty:'Exam',topic:'Superposition signs',title:'Keep a current-only component signed',prompt:'For the same node, a 6 V source feeds A through 3 Ω and a 6 Ω shunt connects A to ground. A 1 A source draws current downward from A. What is the current-source-only contribution to VA?',options:['+6 V','+2 V','−2 V','−6 V'],correctIndex:2,optionFeedback:['Positive six volts ignores current division and the downward source direction.','Positive two volts has the right magnitude but opposite sign.','Correct: with the voltage source shorted, VA″=−1×(3∥6)=−2 V.','Negative six volts treats the node as directly fixed by an ideal source.'],givens:'Current source 1 A downward; voltage source deactivated to a short; 3 Ω∥6 Ω remains.',unknowns:'Signed current-source-only voltage.',answer:'VA″=−2 V.',readAloud:'A downward source removes one ampere from the node. The passive equivalent is three parallel six ohms, or two ohms, so the response is negative two volts.',symbols:'VA″=−ISReq; Req=3∥6=2 Ω.',steps:[S('Deactivate the independent voltage source','R_{eq}=3\\parallel6=2\\ \\Omega','The 3 Ω feed remains connected from A to ground.'),S('Apply the signed source current','V_A\\prime\\prime=-(1)(2)=-2\\ \\mathrm{V}','Current leaving A makes its passive-node voltage negative.')],verification:'The current-only KCL is VA/3+VA/6=−1 A, and VA=−2 V satisfies it.',trap:'Superposition requires signed components; do not report only magnitude.',fastCheck:'One amp out of two ohms gives negative two volts.'}),
O({id:'MCQ-15',kind:'mcq',difficulty:'Exam',topic:'Power after superposition',title:'Add currents before computing power',prompt:'Through a 4 Ω resistor, source 1 alone produces 2 A and source 2 alone produces −0.5 A in the same reference. What is total resistor power with both sources active?',options:['9 W','16 W','17 W','1 W'],correctIndex:0,optionFeedback:['Correct: total current is 1.5 A, so P=4×1.5²=9 W.','Sixteen watts uses only the 2 A component and ignores source 2.','Seventeen watts incorrectly adds separate component powers 16 W and 1 W.','One watt is only the power of the −0.5 A component.'],givens:'R=4 Ω; I′=2 A; I″=−0.5 A.',unknowns:'Total power with both sources active.',answer:'P=9 W.',readAloud:'Superposition adds currents, not powers. The total current is one point five amps, and resistor power is resistance times total current squared.',symbols:'I=I′+I″; P=RI².',steps:[S('Add the signed currents','I=2-0.5=1.5\\ \\mathrm{A}','The second component opposes the first.'),S('Compute power from total current','P=4(1.5)^2=9\\ \\mathrm{W}','Squaring must occur after adding the components.')],verification:'Total resistor voltage is 4×1.5=6 V and VI=6×1.5=9 W.',trap:'Power is quadratic, so separate source powers cannot be superposed.',fastCheck:'One point five squared times four is nine.'}),
O({id:'MCQ-16',kind:'mcq',difficulty:'Exam',topic:'Superposition with dependent sources',title:'Retain dependent sources in every subcircuit',prompt:'A linear circuit has two independent sources and one dependent voltage source. Which superposition procedure is valid?',options:['Deactivate all three sources for each component','Keep the dependent source active in every one-source case','Replace the dependent source by a short in every case','Compute one case with only the dependent source active'],correctIndex:1,optionFeedback:['Dependent sources are not independent excitations and are not switched off.','Correct: only independent sources take turns; the dependent constraint remains active.','A dependent voltage source is not generally zero and cannot automatically be shorted.','With all independent sources zero, the dependent source is not a separate excitation case.'],givens:'Two independent sources and one dependent voltage source in a linear network.',unknowns:'Valid superposition procedure.',answer:'Keep the dependent source and its controlling relation active in every subcircuit.',readAloud:'Superposition separates independent excitations. A dependent source follows the circuit variables, so its constraint stays in place for every case.',symbols:'vx is a controlling variable; the dependent source value changes with each subcircuit solution.',steps:[S('Classify the sources','N_{independent}=2','Only these two sources define separate excitation cases.'),S('Retain the control equation','v_{dep}=f(v_x,i_x)\\quad\\text{in every case}','The dependent relation is part of the network equations, not an independent input.')],verification:'Adding the two complete subcircuit solutions satisfies both the independent-source values and the dependent constraint for the total circuit.',trap:'Turning off a dependent source changes the network and usually changes the answer.',fastCheck:'Independent sources take turns; dependent sources stay.'}),
O({id:'MCQ-17',kind:'mcq',difficulty:'Exam',topic:'Source transformation limits',title:'Do not obscure the controlling variable',prompt:'A branch containing a dependent voltage source is being transformed. Which condition must be preserved?',options:['Its resistance must become zero','Its controlling variable must remain identifiable','Its value must be treated as independent','Its controlling branch must always be removed'],correctIndex:1,optionFeedback:['Source transformation preserves resistance; it does not force zero resistance.','Correct: the transformed equations must still expose the same controlling voltage or current.','A dependent source remains dependent on circuit variables.','Removing the controlling branch would delete the control relationship.'],givens:'A dependent source and a candidate source transformation.',unknowns:'Validity condition for the transformation.',answer:'The controlling variable must remain identifiable and unchanged in meaning.',readAloud:'A source transformation is allowed for a dependent source only when the control voltage or current can still be written after the change.',symbols:'vx or ix is the controlling variable; the dependent source equation must remain equivalent.',steps:[S('Locate the controlling quantity','v_x\\ \\text{or}\\ i_x\\ \\text{must remain defined}','The transformation cannot erase information needed by the source equation.'),S('Compare terminal and control equations','V_{port},I_{port},\\text{ and control relation are unchanged}','Both terminal equivalence and dependence must survive.')],verification:'Solving original and transformed circuits gives the same controlling value and the same port response.',trap:'Preserving only the port V–I relation is insufficient if the control variable disappears.',fastCheck:'Ask where the control variable is measured after transformation.'}),
O({id:'MCQ-18',kind:'mcq',difficulty:'Exam',topic:'Dependent-source nodal analysis',title:'Solve a node with a dependent current source',prompt:'An 8 V source feeds A through 2 Ω. A 4 Ω shunt connects A to ground. A dependent current source draws 0.5vx amperes from A, where vx=VA volts and the gain is 0.5 S. What is VA?',options:['1.6 V','2.4 V','3.2 V','4 V'],correctIndex:2,optionFeedback:['This would make the total leaving current smaller than required by the source feed.','This does not satisfy the three-term KCL with the 0.5 S dependent current.','Correct: (A−8)/2+A/4+0.5A=0 gives A=16/5=3.2 V.','Four volts ignores the dependent-source current.'],givens:'8 V via 2 Ω; 4 Ω shunt; dependent current 0.5VA A leaving.',unknowns:'Node voltage VA.',answer:'VA=16/5=3.2 V.',readAloud:'Write three currents leaving A: through the feed resistor, through the shunt, and through the dependent source. Their sum is zero.',symbols:'A=VA; dependent transconductance is 0.5 S, so its current is 0.5A amperes.',steps:[S('Write KCL including dependence','(A-8)/2+A/4+0.5A=0','The dependent current is not omitted and is expressed directly in terms of A.'),S('Clear denominators and solve','2A-16+A+2A=0\\Rightarrow5A=16\\Rightarrow A=3.2\\ \\mathrm{V}','Multiplying by four gives a one-unknown linear equation.')],verification:'The three signed currents are −2.4 A,0.8 A,1.6 A and sum to zero.',trap:'The dependent source adds a conductance-like term here; it is not an independent 0.5 A source.',fastCheck:'Five A equals sixteen after clearing denominators.'}),
O({id:'MCQ-19',kind:'mcq',difficulty:'Exam',topic:'Dependent-source mesh analysis',title:'Solve a single loop with dependent voltage',prompt:'A 10 V source drives a single loop containing 2 Ω and a dependent voltage source of 3i V opposing the current, where i is loop current. What is i?',options:['1 A','2 A','5 A','10 A'],correctIndex:1,optionFeedback:['One amp would leave an unbalanced 5 V around the loop.','Correct: 10−2i−3i=0 gives i=2 A.','Five amperes uses only the 2 Ω resistor and omits the dependent drop.','Ten amperes confuses voltage with current and ignores resistance.'],givens:'VS=10 V; R=2 Ω; dependent drop=3i V opposing i.',unknowns:'Loop current i.',answer:'i=2 A.',readAloud:'Around the loop, the ten-volt rise balances the resistor drop two i and the dependent-source drop three i.',symbols:'i is loop current; 3i is a voltage because the dependent gain is 3 Ω.',steps:[S('Write KVL with both drops','10-2i-3i=0','The dependent source remains an additional voltage drop.'),S('Combine coefficients and solve','5i=10\\Rightarrow i=2\\ \\mathrm{A}','The dependent source has the same ohmic coefficient effect as a 3 Ω drop in this loop.')],verification:'At 2 A, resistor drop is 4 V and dependent drop is 6 V, totaling 10 V.',trap:'Do not deactivate the dependent source while solving for the independent-source response.',fastCheck:'Two and three ohms equivalent drops give five i.'}),
O({id:'MCQ-20',kind:'mcq',difficulty:'Exam',topic:'Nodal equation count',title:'Combine grounded and floating source constraints',prompt:'A circuit has four non-reference nodes. One grounded voltage source fixes one node. A separate floating voltage source joins two other nodes. How many independent free node-voltage unknowns remain?',options:['1','2','3','4'],correctIndex:1,optionFeedback:['One would require another independent constraint beyond those stated.','Correct: four minus one grounded-source constraint minus one floating constraint leaves two.','Three accounts for the grounded source but not the floating source.','Four ignores both source constraints.'],givens:'Four non-reference nodes; one grounded source; one floating source joining two nodes.',unknowns:'Number of independent free nodal unknowns.',answer:'2 independent free node-voltage unknowns.',readAloud:'The grounded source determines one absolute potential. The floating source determines one difference within a supernode, reducing the remaining independent count by one more.',symbols:'Nfree=4−1−1.',steps:[S('Apply the grounded-source constraint','4-1=3','One node potential becomes known absolutely.'),S('Apply the floating-source constraint','3-1=2','The supernode has two potentials but one independent voltage relation.')],verification:'Two KCL equations plus the two source constraints determine all four original node potentials.',trap:'A floating source does not fix either terminal to ground, but it still reduces independent unknowns.',fastCheck:'Subtract one for each independent ideal voltage constraint.'}),
O({id:'MCQ-21',kind:'mcq',difficulty:'Exam',topic:'Mesh equation count',title:'Count KVL equations with current sources',prompt:'A planar circuit has five meshes and two independent current sources. One source is on an outer branch and one is shared by two meshes. How many independent KVL equations are needed before adding the two current constraints?',options:['2','3','4','5'],correctIndex:1,optionFeedback:['Two would omit one independent mesh KVL relation.','Correct: five meshes minus two current sources gives three KVL equations.','Four subtracts only one of the two current sources.','Five would include KVL around current-source branches whose voltages are unknown.'],givens:'n=5 meshes; m=2 independent current sources.',unknowns:'Number of independent mesh KVL equations.',answer:'3 KVL equations, plus 2 current-source constraints.',readAloud:'Each current source removes one independent KVL equation and supplies one current constraint. Five minus two leaves three.',symbols:'n is mesh count; m is current-source count; n−m is KVL count.',steps:[S('Apply the mesh counting rule','N_{KVL}=n-m=5-2=3','The outer source fixes one mesh current and the shared source supplies a supermesh constraint.'),S('Restore a complete equation set','N_{total}=3+2=5','Three KVL equations and two source constraints determine five mesh currents.')],verification:'The complete system has five independent equations for five unknown mesh currents.',trap:'The shared source needs a supermesh, but it still reduces the KVL count by one.',fastCheck:'Five meshes, two current constraints, three KVL equations.'}),
O({id:'MCQ-22',kind:'mcq',difficulty:'Exam',topic:'Nodal verification',title:'Evaluate a KCL residual',prompt:'At node A=4 V, an 8 Ω shunt goes to ground and a 2 Ω resistor connects to B=1 V. A source injects 2 A into A. What is the KCL residual defined as resistor current leaving minus source current entering?',options:['−1 A','0 A','1 A','2 A'],correctIndex:1,optionFeedback:['A negative one-amp residual would mean one ampere is unaccounted for.','Correct: 4/8+(4−1)/2−2=0.5+1.5−2=0 A.','Positive one ampere results from omitting part of the source injection.','Two amperes counts the source but omits both resistor currents.'],givens:'A=4 V,B=1 V; 8 Ω shunt; 2 Ω coupling; 2 A entering.',unknowns:'Signed KCL residual.',answer:'Residual=0 A.',readAloud:'Current down the shunt is zero point five amps. Current from A to B is one point five amps. Their sum equals the two-amp source injection.',symbols:'r=Iresistor,leaving−Isource,entering is the nodal residual.',steps:[S('Compute both resistor currents','I_8=4/8=0.5\\ \\mathrm{A},\\qquad I_2=(4-1)/2=1.5\\ \\mathrm{A}','Each current uses the node-voltage difference across its own resistor.'),S('Subtract source injection','r=0.5+1.5-2=0\\ \\mathrm{A}','Zero residual confirms conservation at A.')],verification:'Physical branch currents account for exactly the 2 A entering the node.',trap:'A nonzero residual is not a branch current; it signals an unbalanced equation.',fastCheck:'One half plus one and a half equals two.'}),
O({id:'MCQ-23',kind:'mcq',difficulty:'Exam',topic:'Meter loading',title:'Use the Thévenin-meter voltage divider',prompt:'A source has VTh=12 V and RTh=2 kΩ. A voltmeter with 10 kΩ internal resistance is connected across it. What does the meter read?',options:['2 V','10 V','12 V','60 V'],correctIndex:1,optionFeedback:['Two volts confuses the meter current scale with the divider output.','Correct: Vm=12×10/(2+10)=10 V.','Twelve volts would require an ideal infinite-resistance meter.','Sixty volts incorrectly multiplies by the divider ratio denominator.'],givens:'VTh=12 V,RTh=2 kΩ,Rm=10 kΩ.',unknowns:'Loaded meter voltage.',answer:'Vm=10 V.',readAloud:'The meter resistance forms a series path with the Thévenin resistance. Measured voltage is Thévenin voltage times meter resistance divided by their sum.',symbols:'Vm=VThRm/(RTh+Rm).',steps:[S('Form the loaded divider','V_m=12\\frac{10}{2+10}','Both resistances use kΩ, so the ratio is dimensionless.'),S('Evaluate the reading','V_m=12(10/12)=10\\ \\mathrm{V}','The finite meter draws current and lowers the port voltage.')],verification:'Loop current is 12/12 kΩ=1 mA; across 10 kΩ this gives 10 V.',trap:'Open-circuit VTh is not the loaded reading when Rm is finite.',fastCheck:'Ten over twelve of twelve volts is ten.'}),
O({id:'MCQ-24',kind:'mcq',difficulty:'Exam',topic:'Thévenin resistance',title:'Use open-circuit voltage and short-circuit current',prompt:'A linear one-port has open-circuit voltage 18 V and short-circuit current 3 A. What is its Thévenin resistance?',options:['3 Ω','6 Ω','15 Ω','54 Ω'],correctIndex:1,optionFeedback:['Three ohms repeats the current value and fails V/I.','Correct: RTh=Voc/Isc=18/3=6 Ω.','Fifteen ohms subtracts current from voltage with incompatible units.','Fifty-four ohms multiplies instead of dividing.'],givens:'Voc=18 V; Isc=3 A.',unknowns:'Thévenin equivalent resistance.',answer:'RTh=6 Ω.',readAloud:'Open-circuit voltage divided by short-circuit current gives the slope magnitude of the linear port relation, which is Thévenin resistance.',symbols:'RTh=Voc/Isc; units are volts per ampere, or ohms.',steps:[S('Use the two port measurements','R_{Th}=V_{oc}/I_{sc}','The Thévenin model gives Isc=Voc/RTh.'),S('Evaluate the ratio','R_{Th}=18/3=6\\ \\Omega','The resulting unit is V/A=Ω.')],verification:'An 18 V source in series with 6 Ω produces exactly 3 A into a short.',trap:'Do not multiply voltage and current; that gives watts, not resistance.',fastCheck:'Eighteen divided by three is six ohms.'}),
O({id:'MCQ-25',kind:'mcq',difficulty:'Challenge',topic:'Bridge circuits',title:'Recognize a balanced bridge',prompt:'A 10 V source feeds two dividers: 5 Ω over 5 Ω on the left and 10 Ω over 10 Ω on the right. A bridge resistor joins their midpoints A and B. What is the bridge current?',options:['0 A','0.25 A','0.5 A','1 A'],correctIndex:0,optionFeedback:['Correct: both midpoints are 5 V, so the bridge has zero voltage and zero current.','This assumes a nonzero bridge voltage that the balanced dividers do not produce.','This uses an arbitrary 5 V drop across a 10 Ω bridge.','One ampere would violate the equal midpoint potentials.'],givens:'VS=10 V; both divider ratios are 1/2; bridge connects A to B.',unknowns:'Bridge-branch current.',answer:'IAB=0 A because VA=VB=5 V.',readAloud:'Both dividers produce half the source voltage. Equal midpoint potentials mean no voltage across the bridge resistor.',symbols:'VA,VB are midpoint voltages; IAB=(VA−VB)/Rbridge.',steps:[S('Find both midpoint potentials','V_A=10(5/10)=5\\ \\mathrm{V},\\qquad V_B=10(10/20)=5\\ \\mathrm{V}','Different resistor values can still produce the same divider ratio.'),S('Apply Ohm’s law to the bridge','I_{AB}=(5-5)/R_{bridge}=0\\ \\mathrm{A}','Zero voltage across an ordinary resistor gives zero current.')],verification:'Removing the bridge does not change either divider, confirming it carries no current at balance.',trap:'Balance depends on ratios, not on all four resistances being equal.',fastCheck:'Equal divider ratios mean equal midpoints.'}),
O({id:'MCQ-26',kind:'mcq',difficulty:'Challenge',topic:'Method selection for bridges',title:'Choose a method when reduction fails',prompt:'An unbalanced five-resistor bridge has no series–parallel reduction at its input. Which approach most directly finds both midpoint voltages?',options:['Assume the bridge current is zero','Write nodal KCL at the two midpoints','Put every resistor in parallel','Use only the two-branch current-divider rule'],correctIndex:1,optionFeedback:['Zero bridge current applies only to a balanced bridge.','Correct: two midpoint KCL equations include the bridge coupling and source-feed branches.','The bridge resistors do not all share the same two nodes.','Current division alone cannot resolve the cross-connected network.'],givens:'Unbalanced bridge with two midpoint nodes and a cross-branch resistor.',unknowns:'Most direct solution method.',answer:'Write two nodal KCL equations at the midpoints.',readAloud:'The cross-branch couples both midpoint potentials. Nodal analysis handles that coupling directly without assuming balance.',symbols:'VA,VB are midpoint voltages; bridge current is (VA−VB)/Rb.',steps:[S('Assign midpoint variables','V_A,\\quad V_B','Source and ground potentials are already known.'),S('Write coupled KCL equations','\\sum I_{leave,A}=0,\\qquad \\sum I_{leave,B}=0','Each equation includes the shared bridge current with opposite signs.')],verification:'The solved potentials reproduce all five resistor currents and total source current by KCL.',trap:'Do not force a balanced shortcut onto an unbalanced network.',fastCheck:'Two unknown midpoints means two nodal equations.'}),
O({id:'MCQ-27',kind:'mcq',difficulty:'Challenge',topic:'Test-source resistance',title:'Measure equivalent resistance with a test source',prompt:'A 10 V test source is applied to a one-port containing dependent sources. The measured current entering its positive terminal is 2.5 A. What is the port resistance?',options:['0.25 Ω','4 Ω','7.5 Ω','25 Ω'],correctIndex:1,optionFeedback:['This is test current divided by voltage, the conductance in siemens.','Correct: Rtest=Vtest/Itest=10/2.5=4 Ω.','This subtracts current from voltage and has no resistance meaning.','This multiplies voltage by current and gives power, not resistance.'],givens:'Vtest=10 V; Itest=2.5 A entering the positive terminal.',unknowns:'One-port equivalent resistance.',answer:'Req=4 Ω.',readAloud:'With independent sources deactivated and dependent sources retained, apply a test voltage. Resistance is test voltage divided by resulting current.',symbols:'Req=Vtest/Itest; one volt per ampere is one ohm.',steps:[S('Use the test-source definition','R_{eq}=V_{test}/I_{test}','The port V–I ratio defines equivalent resistance.'),S('Evaluate the measurement','R_{eq}=10/2.5=4\\ \\Omega','Divide volts by amperes; one volt per ampere is one ohm of equivalent resistance.')],verification:'A 4 Ω resistor would draw exactly 2.5 A from a 10 V test source.',trap:'Dependent sources stay active during the test; only independent sources are deactivated.',fastCheck:'Ten divided by two point five is four.'}),
O({id:'MCQ-28',kind:'mcq',difficulty:'Challenge',topic:'Three-source superposition',title:'Add three signed voltage components',prompt:'At one node, three independent sources acting separately produce voltage contributions +4 V,−1.5 V,and +2 V. What is the total node voltage?',options:['0.5 V','2.5 V','4.5 V','7.5 V'],correctIndex:2,optionFeedback:['This subtracts the positive 4 V contribution instead of adding it.','This omits the +2 V contribution.','Correct: 4−1.5+2=4.5 V.','This treats the −1.5 V component as positive.'],givens:'V′=4 V,V″=−1.5 V,V‴=2 V.',unknowns:'Total node voltage.',answer:'V=4.5 V.',readAloud:'Superposition adds signed responses. Four minus one point five plus two equals four point five volts.',symbols:'V=V′+V″+V‴; each prime labels one independent-source response.',steps:[S('Write the signed sum','V=4+(-1.5)+2','The negative component remains negative in the total.'),S('Evaluate with common units','V=4.5\\ \\mathrm{V}','All three contributions use the same node and polarity.')],verification:'The total differs from the all-positive sum 7.5 V by 3 V, exactly twice the negative component magnitude.',trap:'Do not add magnitudes when a source component opposes the selected polarity.',fastCheck:'Four plus two minus one point five is four point five.'}),
O({id:'MCQ-29',kind:'mcq',difficulty:'Stretch',topic:'Superposition with a dependent source',title:'Solve dependent-network source components',prompt:'Node A obeys 3A=VS+IS, where VS is in volts and IS numerically in amperes after unit scaling. The dependent-source term is already included in the coefficient 3. With VS=6 V and IS=3 A, what is total A?',options:['1 V','2 V','3 V','9 V'],correctIndex:2,optionFeedback:['One volt is only the current-source component.','Two volts is only the voltage-source component.','Correct: VS-only gives 2 V, IS-only gives 1 V, and total A=3 V.','Nine volts adds source magnitudes without applying the network coefficient.'],givens:'Scaled linear relation 3A=VS+IS; VS=6,IS=3.',unknowns:'Total node voltage using source components.',answer:'A=3 V; components are 2 V and 1 V.',readAloud:'For the voltage-source case, current excitation is zero and A equals two. For the current-source case, voltage excitation is zero and A equals one. Add them.',symbols:'A′=VS/3; A″=IS/3 under the stated scaled units.',steps:[S('Compute independent responses','A\\prime=6/3=2\\ \\mathrm{V},\\qquad A\\prime\\prime=3/3=1\\ \\mathrm{V}','The dependent-source coefficient remains in both equations.'),S('Add and check the total relation','A=2+1=3\\ \\mathrm{V}\\Rightarrow3A=9=6+3','The total satisfies the original scaled equation directly.')],verification:'Both component equations and the total equation have zero residual.',trap:'Do not remove the dependent-source contribution when switching independent sources.',fastCheck:'Two volts plus one volt gives three volts.'}),
O({id:'MCQ-30',kind:'mcq',difficulty:'Stretch',topic:'Multiple source transformations',title:'Combine three source-fed branches',prompt:'Node A connects to 18 V through 6 Ω,to 6 V through 3 Ω,and to ground through 6 Ω. What is VA?',options:['5 V','7.5 V','10 V','12 V'],correctIndex:1,optionFeedback:['Five volts would make the three resistor currents fail to sum to zero.','Correct: (A−18)/6+(A−6)/3+A/6=0 gives 4A=30 and A=7.5 V.','Ten volts exceeds the weighted source-feed result and violates KCL.','Twelve volts treats the two sources as a simple series aid without the shunt.'],givens:'18 V via 6 Ω; 6 V via 3 Ω; 6 Ω shunt.',unknowns:'Common node voltage.',answer:'VA=7.5 V.',readAloud:'Transform each source-feed branch into a Norton branch. Clear the conductance denominators and solve for the common node voltage.',symbols:'A=VA; resistor currents leaving A are (A−18)/6,(A−6)/3,A/6.',steps:[S('Write the three-branch KCL','(A-18)/6+(A-6)/3+A/6=0','Each branch retains its source offset and resistance.'),S('Clear denominators and solve','A-18+2A-12+A=0\\Rightarrow4A=30\\Rightarrow A=7.5\\ \\mathrm{V}','Multiplying by six yields a simple hand-solvable equation.')],verification:'The signed branch currents are −1.75 A,+0.5 A,+1.25 A and sum to zero.',trap:'Do not average source voltages without including branch conductances and the shunt.',fastCheck:'Four A equals thirty after clearing denominators.'}),
O({id:'SHORT-01',kind:'short',difficulty:'Guided',topic:'Two-node hand solution',title:'Solve a two-node ladder without a matrix tool',prompt:'An 18 V source feeds A through 3 Ω. A has a 6 Ω shunt and a 6 Ω connection to B. B has a 3 Ω shunt. Find A and B by hand.',givens:'VS=18 V; feed 3 Ω; shunts 6 Ω at A and 3 Ω at B; coupling 6 Ω.',unknowns:'Node voltages A and B.',answer:'A=108/11=9.81818 V and B=36/11=3.27273 V.',readAloud:'Write KCL at B first because it gives A equals three B. Substitute that ratio into the A-node balance.',symbols:'A,B are node voltages; resistor current equals voltage difference divided by resistance.',steps:[S('Write both nodal balances','(A-18)/3+A/6+(A-B)/6=0,\\qquad (B-A)/6+B/3=0','Every branch connected to A or B appears once with the correct voltage difference.'),S('Use the B-node ratio','-A+3B=0\\Rightarrow A=3B','Multiplying the B equation by six gives a direct node-voltage ratio.'),S('Substitute into the A equation','4A-B=36\\Rightarrow12B-B=36\\Rightarrow B=36/11\\ \\mathrm{V},\\quad A=108/11\\ \\mathrm{V}','Scaling the A equation by six gives 4A−B=36 before substitution.')],verification:'At B,(36/11−108/11)/6+(36/11)/3=−12/11+12/11=0 A; at A the signed currents also sum to zero.',trap:'The 6 Ω coupling current uses A−B, not A alone.'}),
O({id:'SHORT-02',kind:'short',difficulty:'Guided',topic:'Supernode calculation',title:'Find supernode voltages and source current',prompt:'Nodes A and B are joined by a 3 V source with B positive. Shunts are 2 Ω at A and 6 Ω at B; a 4 Ω resistor also joins A to B. Find A,B,and current from A to B through the source.',givens:'B−A=3 V; external shunts 2 Ω and 6 Ω; internal resistor 4 Ω.',unknowns:'Two node voltages and source current iAB.',answer:'A=−0.75 V,B=2.25 V; iAB=1.125 A from A to B.',readAloud:'The four-ohm resistor and ideal source are both internal to the supernode, so only shunt currents enter its KCL. Return to node A to find source current.',symbols:'iAB is source current leaving A; the internal resistor current is (A−B)/4.',steps:[S('Write supernode KCL and constraint','A/2+B/6=0,\\qquad B-A=3','Internal source and resistor currents cancel around the enclosure.'),S('Solve the two equations','3A+B=0,\\quad B=A+3\\Rightarrow A=-0.75\\ \\mathrm{V},\\quad B=2.25\\ \\mathrm{V}','Substitution gives 4A+3=0 and then both potentials.'),S('Recover source current at A','i_{AB}=-[A/2+(A-B)/4]=-[-0.375-0.75]=1.125\\ \\mathrm{A}','KCL at A includes its shunt and internal resistor currents.')],verification:'At B, resistor currents are B/6=0.375 A and (B−A)/4=0.75 A, balanced by 1.125 A entering through the source.',trap:'Do not omit the internal 4 Ω resistor when returning to a single node for source current.'}),
O({id:'SHORT-03',kind:'short',difficulty:'Guided',topic:'Two-mesh hand solution',title:'Solve mesh currents and shared-resistor voltage',prompt:'Two meshes obey 6i1−2i2=12 and −2i1+4i2=0. Find i1,i2,and the voltage across the 2 Ω shared resistor under the i1−i2 reference.',givens:'Two KVL equations; shared resistance R=2 Ω.',unknowns:'Mesh currents and shared-branch voltage.',answer:'i1=2.4 A,i2=1.2 A; shared current=1.2 A and shared voltage=2.4 V.',readAloud:'The second equation gives i two as half i one. Solve the mesh currents first, then apply Ohm’s law to their difference.',symbols:'vshared=2(i1−i2), positive under the i1 direction.',steps:[S('Eliminate one mesh current','i_2=i_1/2\\Rightarrow6i_1-i_1=12','Substitution reduces the system to 5i1=12.'),S('Recover both currents','i_1=2.4\\ \\mathrm{A},\\qquad i_2=1.2\\ \\mathrm{A}','Back-substitution gives the second mesh current.'),S('Apply Ohm’s law to the difference','v_{shared}=2(2.4-1.2)=2.4\\ \\mathrm{V}','The shared resistor does not carry i1 alone.')],verification:'Both KVL equations hold, and the shared current is 2.4 V/2 Ω=1.2 A.',trap:'A tidy mesh answer still needs conversion to the requested branch quantity.'}),
O({id:'SHORT-04',kind:'short',difficulty:'Guided',topic:'Supermesh calculation',title:'Use a current constraint and one supermesh',prompt:'Two clockwise meshes share a 2 A upward source. Mesh 1 travels down the shared branch and mesh 2 travels up it. Mesh 1 has an outer 2 Ω resistor and 6 V rise; mesh 2 has an outer 2 Ω resistor; their shared resistor is 4 Ω. Find both currents.',givens:'i2−i1=2 A; outer resistors 2 Ω each; shared resistor 4 Ω; 6 V rise in mesh 1.',unknowns:'Mesh currents i1 and i2.',answer:'i1=2.5 A and i2=4.5 A.',readAloud:'The source constraint is i two minus i one equals two. Around the supermesh, resistor drops are two i one, four times i one minus i two, and two i two.',symbols:'i1,i2 are clockwise mesh currents; the 6 V source is the only independent voltage rise.',steps:[S('Write the source constraint','i_2-i_1=2\\Rightarrow i_2=i_1+2','The two mesh currents oppose on the shared source branch.'),S('Write supermesh KVL','2i_1+4(i_1-i_2)+2i_2=6\\Rightarrow6i_1-2i_2=6','The current-source voltage is excluded from the supermesh path.'),S('Substitute and solve','6i_1-2(i_1+2)=6\\Rightarrow4i_1=10\\Rightarrow i_1=2.5\\ \\mathrm{A},\\ i_2=4.5\\ \\mathrm{A}','The current constraint then gives i2 immediately.')],verification:'i2−i1=2 A and 2(2.5)+4(−2)+2(4.5)=5−8+9=6 V.',trap:'The shared 4 Ω current is i1−i2, not i1+i2.'}),
O({id:'SHORT-05',kind:'short',difficulty:'Core',topic:'Dependent nodal analysis and power',title:'Solve a dependent-current node and source power',prompt:'An 8 V source feeds A through 2 Ω. A has a 4 Ω shunt and a dependent current source drawing 0.5VA amperes from A. Find A,all branch currents,and power delivered by the 8 V source.',givens:'8 V via 2 Ω; 4 Ω shunt; dependent transconductance 0.5 S.',unknowns:'Node voltage,three currents,and independent-source power.',answer:'A=3.2 V; source-feed current=2.4 A toward A,shunt current=0.8 A down,dependent current=1.6 A leaving; source delivers 19.2 W.',readAloud:'The dependent current is one half times A amperes. KCL determines A, and independent-source power is eight volts times the current leaving its positive terminal.',symbols:'Ifeed=(8−A)/2; Pdel=8Ifeed.',steps:[S('Write dependent-node KCL','(A-8)/2+A/4+0.5A=0','All three currents leaving A are included.'),S('Solve for A','2A-16+A+2A=0\\Rightarrow A=16/5=3.2\\ \\mathrm{V}','Clearing denominators produces 5A=16.'),S('Recover currents and power','I_{feed}=2.4\\ \\mathrm{A},\\ I_4=0.8\\ \\mathrm{A},\\ I_{dep}=1.6\\ \\mathrm{A};\\quad P_{del}=8(2.4)=19.2\\ \\mathrm{W}','The source current flows from its positive terminal into the network.')],verification:'KCL gives 2.4=0.8+1.6 A. The feed resistor absorbs 11.52 W, the shunt 2.56 W, and the dependent source 5.12 W, totaling 19.2 W.',trap:'Use total source current for power; do not apply superposition to power terms.'}),
O({id:'SHORT-06',kind:'short',difficulty:'Core',topic:'Dependent mesh analysis',title:'Find loop current and controlling voltage',prompt:'A 10 V source drives a loop with 2 Ω and a dependent voltage source 3i V opposing current. Find i,the resistor voltage vx,and the dependent-source voltage.',givens:'VS=10 V,R=2 Ω,dependent gain 3 Ω.',unknowns:'Loop current and both element voltages.',answer:'i=2 A; vx=4 V; dependent-source voltage=6 V opposing current.',readAloud:'KVL adds the resistive drop two i and dependent drop three i. Once current is known, Ohm’s law gives the controlling resistor voltage.',symbols:'vx=2i; vdep=3i; both are voltage drops in the loop direction.',steps:[S('Write KVL','10-2i-3i=0','The dependent source stays active in the loop equation.'),S('Solve current','5i=10\\Rightarrow i=2\\ \\mathrm{A}','The two voltage drops have coefficients totaling five ohms.'),S('Evaluate both voltages','v_x=2(2)=4\\ \\mathrm{V},\\qquad v_{dep}=3(2)=6\\ \\mathrm{V}','Each voltage follows from the same solved loop current.')],verification:'The 4 V and 6 V drops sum to the 10 V source rise.',trap:'The dependent value 3i has volts, while i itself has amperes.'}),
O({id:'SHORT-07',kind:'short',difficulty:'Core',topic:'Source transformation',title:'Transform, combine, and find terminal voltage',prompt:'A 36 V source in series with 6 Ω feeds a node that also has a 3 Ω shunt. Use source transformation to find the node voltage.',givens:'VTh=36 V,series 6 Ω; parallel load 3 Ω.',unknowns:'Terminal node voltage.',answer:'Norton equivalent is 6 A in parallel with 6 Ω; combined resistance=2 Ω; terminal voltage=12 V.',readAloud:'Thirty-six divided by six gives a six-amp Norton source. Six parallel three gives two ohms, so terminal voltage is six times two.',symbols:'IN=VTh/R; RN=6∥3; V=INRN.',steps:[S('Transform the source branch','I_N=36/6=6\\ \\mathrm{A},\\qquad R_N=6\\ \\Omega','The 6 Ω resistance moves from series to parallel without changing value.'),S('Combine parallel resistances','R_{eq}=6\\parallel3=2\\ \\Omega','The Norton resistance and load share both nodes.'),S('Find open-node terminal voltage','V=I_NR_{eq}=6(2)=12\\ \\mathrm{V}','All 6 A flows through the equivalent 2 Ω in the reduced model.')],verification:'Original series current is (36−12)/6=4 A and load current is 12/3=4 A.',trap:'After transformation, combine 6 Ω and 3 Ω in parallel, not series.'}),
O({id:'SHORT-08',kind:'short',difficulty:'Core',topic:'Two-source superposition',title:'Find node voltage and shunt current by superposition',prompt:'Node A connects to 10 V through 5 Ω,to ground through 10 Ω,and receives 2 A upward. Find both source contributions to A,total A,and total shunt current.',givens:'10 V via 5 Ω; 10 Ω shunt; 2 A injected.',unknowns:'Two voltage components,total voltage,and shunt current.',answer:'VA′=20/3 V,VA″=20/3 V,VA=40/3=13.3333 V; shunt current=4/3 A downward.',readAloud:'The voltage-only response uses a divider. The current-only response uses five parallel ten ohms. Add voltages, then divide total voltage by ten ohms.',symbols:'VA=VA′+VA″; Ishunt=VA/10.',steps:[S('Voltage source acting alone','V_A\\prime=10\\frac{10}{5+10}=20/3\\ \\mathrm{V}','Open the independent current source.'),S('Current source acting alone','V_A\\prime\\prime=2(5\\parallel10)=20/3\\ \\mathrm{V}','Short the ideal voltage source but retain the 5 Ω resistor.'),S('Add and recover current','V_A=40/3\\ \\mathrm{V},\\qquad I_{shunt}=(40/3)/10=4/3\\ \\mathrm{A}','The physical shunt current comes from the total voltage, not separate powers.')],verification:'Total KCL at A gives (40/3−10)/5+(40/3)/10=2/3+4/3=2 A.',trap:'Do not short the 5 Ω resistor when deactivating its ideal source.'}),
O({id:'SHORT-09',kind:'short',difficulty:'Core',topic:'Three-source superposition',title:'Separate two voltage responses and one current response',prompt:'Node A connects to 12 V through 4 Ω,to 6 V through 2 Ω,and to ground through 4 Ω. A 1 A source draws current downward from A. Find the three contributions and total A.',givens:'Two voltage-feed branches and one downward 1 A source; 4 Ω shunt.',unknowns:'Three signed voltage components and total node voltage.',answer:'12 V source:3 V;6 V source:3 V;current source:−1 V;total A=5 V.',readAloud:'The three passive conductances total one siemens. Each voltage source acting alone produces three volts. The downward current source alone produces negative one volt.',symbols:'A=A12+A6+AI; all components use volts at node A.',steps:[S('Find each voltage-source response','A_{12}=12\\frac{1/4}{1}=3\\ \\mathrm{V},\\qquad A_6=6\\frac{1/2}{1}=3\\ \\mathrm{V}','With other independent sources deactivated, total conductance remains 1 S.'),S('Find the current-source response','A_I=-1/(1)=-1\\ \\mathrm{V}','One ampere leaving through 1 S produces −1 V.'),S('Add and solve the total directly','A=3+3-1=5\\ \\mathrm{V};\\qquad(A-12)/4+(A-6)/2+A/4=-1','The direct total KCL provides an independent comparison.')],verification:'At A=5 V,branch currents are −1.75 A,−0.5 A,1.25 A and sum to −1 A,matching the downward source.',trap:'The 6 V source has a different feed resistance, so do not reuse the 12 V divider blindly.'}),
O({id:'SHORT-10',kind:'short',difficulty:'Core',topic:'Ladder expansion and current recovery',title:'Reduce a ladder then recover every branch current',prompt:'A 24 V source feeds 2 Ω followed by a 12 Ω branch in parallel with a second branch: 4 Ω in series with a 6 Ω∥3 Ω pair. Find Req,source current,and all branch currents.',givens:'VS=24 V; input 2 Ω; downstream 12 Ω∥[4+(6∥3)] Ω.',unknowns:'Equivalent resistance and currents through 12 Ω,4 Ω,6 Ω,and 3 Ω.',answer:'Req=6 Ω,Is=4 A; downstream voltage=16 V; I12=4/3 A,I4=8/3 A,I6=8/9 A,I3=16/9 A.',readAloud:'Six parallel three is two, plus four is six. Twelve parallel six is four, plus input two is six. Expand the ladder and divide current at each level.',symbols:'Rd=12∥6=4 Ω; Vd is downstream-node voltage.',steps:[S('Reduce toward the source','6\\parallel3=2\\ \\Omega,\\quad4+2=6\\ \\Omega,\\quad12\\parallel6=4\\ \\Omega,\\quad R_{eq}=2+4=6\\ \\Omega','Each reduction respects series and parallel terminal pairs.'),S('Find total and first-level currents','I_s=24/6=4\\ \\mathrm{A},\\quad V_d=24-4(2)=16\\ \\mathrm{V};\\quad I_{12}=16/12=4/3\\ \\mathrm{A},\\ I_4=16/6=8/3\\ \\mathrm{A}','The two downstream currents sum to the 4 A source current.'),S('Divide the second branch current','V_{6\\parallel3}=16-(8/3)4=16/3\\ \\mathrm{V};\\quad I_6=8/9\\ \\mathrm{A},\\quad I_3=16/9\\ \\mathrm{A}','The 6 Ω and 3 Ω currents sum to 24/9=8/3 A.')],verification:'KCL holds at both junctions, and source power 96 W equals total I²R dissipation.',trap:'The 4 Ω resistor carries 8/3 A before the final current split, not the total 4 A.'}),
O({id:'SHORT-11',kind:'short',difficulty:'Exam',topic:'Thévenin meter loading',title:'Calculate meter reading and loading error',prompt:'A one-port has VTh=24 V and RTh=4 kΩ. A 12 kΩ voltmeter is attached. Find the reading,meter current,and percentage reduction from VTh.',givens:'VTh=24 V,RTh=4 kΩ,Rm=12 kΩ.',unknowns:'Loaded voltage,meter current,and loading error.',answer:'Vm=18 V; Im=1.5 mA; reading is 25% below the 24 V open-circuit value.',readAloud:'The total series resistance is sixteen kilo-ohms. Current is twenty-four divided by sixteen milliamps, and meter voltage is current times twelve kilo-ohms.',symbols:'Im=VTh/(RTh+Rm); error=(VTh−Vm)/VTh×100%.',steps:[S('Find loaded-loop current','I_m=24/(4+12)=1.5\\ \\mathrm{mA}','Using V/kΩ gives current in mA directly.'),S('Find meter voltage','V_m=I_mR_m=(1.5)(12)=18\\ \\mathrm{V}','The reading is the drop across the 12 kΩ meter.'),S('Compute percentage reduction','E=\\frac{24-18}{24}100\\%=25\\%','Compare the loaded reading with open-circuit VTh.')],verification:'Voltage division gives 24×12/(4+12)=18 V, and the RTh drop is 24−18=6 V.',trap:'Do not call the 24 V open-circuit value the measured voltage.'}),
O({id:'SHORT-12',kind:'short',difficulty:'Exam',topic:'Method selection and supernode solution',title:'Choose nodal analysis then solve the reduced system',prompt:'A circuit has three non-reference nodes. One is fixed by a grounded source; the other two,A and B,are joined by a floating source with B=A+3 V. Their only external shunts are 2 Ω and 6 Ω. Explain the efficient formulation and solve A,B.',givens:'One ground-fixed node; one A–B supernode; shunts 2 Ω and 6 Ω.',unknowns:'Equation count and the two unknown potentials.',answer:'Only one supernode KCL plus one source constraint is needed; A=−0.75 V,B=2.25 V.',readAloud:'The grounded node is already known. The floating source joins the remaining nodes into one supernode, so write one current balance and one voltage difference.',symbols:'A,B are unknown potentials; B−A=3 V.',steps:[S('Select the reduced formulation','N_{KCL}=1,\\qquad N_{constraint}=1','Two unknown potentials require two equations after the grounded node is removed.'),S('Write supernode and source equations','A/2+B/6=0,\\qquad B-A=3','Only external shunt currents cross the supernode boundary.'),S('Solve by substitution','3A+B=0,\\quad B=A+3\\Rightarrow A=-0.75\\ \\mathrm{V},\\ B=2.25\\ \\mathrm{V}','Substitution gives 4A+3=0.')],verification:'The shunt currents are −0.375 A and 0.375 A,which sum to zero,and B−A=3 V.',trap:'Do not write separate KCL at A and B with the same unknown source current twice.'}),
O({id:'SHORT-13',kind:'short',difficulty:'Exam',topic:'Power and superposition',title:'Show why power components cannot be added',prompt:'Two independent sources acting alone drive 3 A and −1 A through a 5 Ω resistor in the same reference. Find total current,voltage,and power;compare with the sum of separate component powers.',givens:'R=5 Ω,I′=3 A,I″=−1 A.',unknowns:'Total electrical response and the invalid component-power sum.',answer:'I=2 A,V=10 V,P=20 W. Separate powers are 45 W and 5 W,whose 50 W sum is not the physical power.',readAloud:'Add currents first to obtain two amps. Power is five times the square of total current, not the sum of five times each component squared.',symbols:'P=R(I′+I″)²; P′=RI′² and P″=RI″² are diagnostic quantities only.',steps:[S('Add signed current components','I=3-1=2\\ \\mathrm{A}','The negative component reduces total current.'),S('Compute total voltage and power','V=5(2)=10\\ \\mathrm{V},\\qquad P=5(2)^2=20\\ \\mathrm{W}','Both quantities use total current with both sources active.'),S('Evaluate the contrast','P\\prime+P\\prime\\prime=5(3)^2+5(-1)^2=50\\ \\mathrm{W}\\ne20\\ \\mathrm{W}','The cross term 2RI′I″=−30 W explains the difference algebraically.')],verification:'VI=10×2=20 W matches I²R,while direct component addition fails.',trap:'Superposition applies to linear voltage and current,not quadratic power.'}),
O({id:'SHORT-14',kind:'short',difficulty:'Challenge',topic:'Dependent-network test source',title:'Find port resistance and test-source power',prompt:'After independent sources in a dependent-source one-port are deactivated,a 5 V test source drives 1.25 A into its positive terminal. Find equivalent resistance and power absorbed by the network.',givens:'Vtest=5 V,Itest=1.25 A entering the positive terminal.',unknowns:'Port resistance and absorbed test power.',answer:'Req=4 Ω; network absorbs 6.25 W from the test source.',readAloud:'Resistance is test voltage divided by current. Current enters the positive terminal,so absorbed power is positive voltage times current.',symbols:'Req=Vtest/Itest; Pabs=VtestItest.',steps:[S('Compute the V–I ratio','R_{eq}=5/1.25=4\\ \\Omega','The test measurement directly determines port resistance.'),S('Apply passive sign convention','P_{abs}=5(1.25)=6.25\\ \\mathrm{W}','Current enters the positive terminal,so the network absorbs power.'),S('Check with resistance power','P=I^2R=(1.25)^2(4)=6.25\\ \\mathrm{W}','The equivalent-resistance power formula independently agrees.')],verification:'Ohm’s law,V=IR=1.25×4=5 V,reproduces the test voltage.',trap:'Retain dependent sources during the test;deactivating them would measure a different network.'}),
O({id:'LONG-01',kind:'long',difficulty:'Exam',topic:'Three-node nodal analysis and power',title:'Complete nodal solution with branch-current and power audit',time:18,prompt:'A 12 V source feeds A through 2 Ω. A has a 3 Ω shunt,a 1 Ω link to B,and a 1 A source drawing current from A. B has a 4 Ω shunt and a 2 Ω link to C. C has a 2 Ω shunt.',parts:['Write and solve the three nodal equations.','Find every resistor current and the 12 V source current.','Determine source powers and verify the complete power balance.'],givens:'12 V via 2 Ω; shunts 3 Ω,4 Ω,2 Ω; links 1 Ω and 2 Ω; 1 A drawn from A.',unknowns:'A,B,C,all branch currents,and power roles.',answer:'A=30/7=4.285714 V,B=20/7=2.857143 V,C=10/7=1.428571 V. Feed current=27/7=3.857143 A toward A; shunt currents=10/7 A,5/7 A,5/7 A; link currents=10/7 A and 5/7 A. The 12 V source delivers 324/7=46.285714 W and the 1 A source absorbs 30/7=4.285714 W; resistors absorb 42 W.',readAloud:'Write resistor currents leaving each node. At A include the additional one-ampere source leaving. Solve the equations,then multiply voltage and current for each power term.',symbols:'A,B,C are node potentials; currents are positive from the first named node to the second or downward to ground.',steps:[S('Write the three KCL equations','(A-12)/2+A/3+(A-B)+1=0,\\quad(B-A)+B/4+(B-C)/2=0,\\quad(C-B)/2+C/2=0','The independent 1 A source appears only at A,while each coupling current appears with opposite signs at adjacent nodes.'),S('Solve the coupled system','A=30/7\\ \\mathrm{V},\\qquad B=20/7\\ \\mathrm{V},\\qquad C=10/7\\ \\mathrm{V}','The C equation gives C=B/2; back-substitution into B and A yields these exact sevenths.'),S('Recover all currents','I_{feed}=27/7\\ \\mathrm{A},\\ I_{3}=10/7\\ \\mathrm{A},\\ I_{AB}=10/7\\ \\mathrm{A},\\ I_4=5/7\\ \\mathrm{A},\\ I_{BC}=5/7\\ \\mathrm{A},\\ I_C=5/7\\ \\mathrm{A}','Each current follows from its own Ohm’s-law voltage difference.'),
S('Balance power','P_{12V,del}=12(27/7)=324/7\\ \\mathrm{W},\\quad P_{1A,abs}=30/7\\ \\mathrm{W},\\quad P_R=(1458+300+100+100+50+50)/49=42\\ \\mathrm{W}','The 324/7 W delivered by the voltage source equals 42 W of resistor absorption plus 30/7 W absorbed by the current source.')],verification:'All three KCL residuals vanish. The complete power balance is 324/7 W delivered = 42 W + 30/7 W absorbed, or 46.285714 W on both sides.',trap:'Include the 1 A source at A and use total currents in the power check.',marks:[['Correct three-node KCL system with source sign',5],['Correct node voltages with hand-solution work',5],['All branch currents with directions',5],['Source and resistor power balance',5]]}),
O({id:'LONG-02',kind:'long',difficulty:'Exam',topic:'Supernode currents and source power',title:'Solve a loaded supernode and audit every source',time:20,prompt:'A 12 V source feeds A through 2 Ω. A has a 4 Ω shunt. B has a 3 Ω shunt. A and B are joined by a 6 Ω resistor and a 6 V source with B positive. A 1 A source injects current into B.',parts:['Form the supernode equation and solve A,B.','Find resistor currents and current through the 6 V source.','Compute all three source powers and verify conservation.'],givens:'B−A=6 V; 12 V via 2 Ω; shunts 4 Ω and 3 Ω; internal 6 Ω; 1 A into B.',unknowns:'Node voltages,branch currents,and source powers.',answer:'A=60/13=4.61538 V,B=138/13=10.61538 V. Feed current=48/13=3.69231 A toward A; shunt currents=15/13 A and 46/13 A; internal current=1 A from B to A; voltage-source current=46/13 A from A to B. The 12 V source delivers 576/13=44.3077 W,the 6 V source delivers 276/13=21.2308 W,and the 1 A source delivers 138/13=10.6154 W.',readAloud:'The six-volt source and six-ohm resistor are internal to the A–B supernode. Write external currents,then return to node A for source current and use terminal directions for power.',symbols:'A,B are node voltages;iV is positive from A to B through the 6 V source.',steps:[S('Write supernode KCL','(A-12)/2+A/4+B/3=1,\\qquad B-A=6','The independent current source injects 1 A into the enclosure;internal branch currents cancel.'),S('Solve for both potentials','9A+4B=84,\\quad B=A+6\\Rightarrow A=60/13\\ \\mathrm{V},\\ B=138/13\\ \\mathrm{V}','Substitution gives 13A=60 and fixes B immediately.'),S('Recover branch and source currents','I_{feed}=48/13\\ \\mathrm{A},\\ I_{4}=15/13\\ \\mathrm{A},\\ I_3=46/13\\ \\mathrm{A},\\ I_{BA,6\\Omega}=1\\ \\mathrm{A},\\ i_V=46/13\\ \\mathrm{A}','The internal resistor drop is exactly 6 V,so its current is 1 A;KCL at A then gives iV.'),
S('Assign power roles','P_{12,del}=12(48/13)=576/13\\ \\mathrm{W},\\quad P_{6,del}=6(46/13)=276/13\\ \\mathrm{W},\\quad P_{1A,del}=B(1)=138/13\\ \\mathrm{W}','Current enters the 6 V source at its negative terminal,so it delivers;the 1 A current also leaves the source at positive B,so that source delivers too.')],verification:'KCL holds at A,B,and the supernode. Resistor absorption is 990/13 W, equal to total source delivery (576+276+138)/13=990/13 W.',trap:'Do not omit the internal 6 Ω current when finding the voltage-source current.',marks:[['Correct supernode KCL and voltage constraint',5],['Correct node-voltage solution',5],['Complete branch and source-current recovery',5],['Correct power roles and conservation audit',5]]}),
O({id:'LONG-03',kind:'long',difficulty:'Exam',topic:'Three-mesh supermesh analysis',title:'Solve three meshes with a shared current source',time:20,prompt:'Three clockwise meshes have a 10 V rise in mesh 1. Mesh 1 has outer 2 Ω and shares 2 Ω with mesh 2. Mesh 2 has outer 1 Ω. Mesh 3 has outer 3 Ω and 1 Ω. A 3 A source shared by meshes 2 and 3 points upward;mesh 2 goes down that branch and mesh 3 goes up.',parts:['Write the current constraint,left-mesh KVL,and supermesh KVL.','Solve all three mesh currents.','Recover shared-branch currents and verify all equations.'],givens:'10 V rise;resistances 2,2,1,3,1 Ω;shared source 3 A.',unknowns:'i1,i2,i3 and physical shared-branch currents.',answer:'i1=23/12=1.91667 A,i2=−7/6=−1.16667 A,i3=11/6=1.83333 A. The 2 Ω shared current is i1−i2=37/12=3.08333 A;the current-source constraint is i3−i2=3 A.',readAloud:'The shared current source gives i three minus i two equals three. The left mesh and the outer supermesh supply the two KVL equations.',symbols:'i1,i2,i3 are clockwise mesh currents;shared 2 Ω current follows i1−i2.',steps:[S('Write constraint and left-mesh KVL','i_3-i_2=3,\\qquad4i_1-2i_2=10','Mesh 1 self-resistance is 2+2=4 Ω.'),S('Write supermesh KVL','-2i_1+3i_2+4i_3=0','The supermesh includes the shared-left 2 Ω,middle 1 Ω,and right 3+1 Ω paths.'),S('Solve the three equations','i_3=11/6\\ \\mathrm{A},\\qquad i_2=-7/6\\ \\mathrm{A},\\qquad i_1=23/12\\ \\mathrm{A}','Use i2=i3−3 and 2i1−i3=2 to reduce the supermesh to 6i3=11.'),S('Recover the resistor-branch current','i_{2\\Omega}=i_1-i_2=23/12+14/12=37/12=3.08333\\ \\mathrm{A}','The negative i2 reverses its assumed direction and increases the shared-branch difference.')],verification:'The constraint is 11/6+7/6=3 A;left KVL is 4(23/12)−2(−7/6)=10 V;supermesh KVL evaluates to zero.',trap:'The 3 A source does not fix i3 alone,and negative mesh current is physically valid.',marks:[['Correct current-source constraint and left KVL',5],['Correct supermesh KVL with all resistor terms',5],['Correct three mesh currents',5],['Branch-current recovery and substitution audit',5]]}),
O({id:'LONG-04',kind:'long',difficulty:'Exam',topic:'Dependent-source nodal power audit',title:'Solve a dependent-current network completely',time:18,prompt:'An 8 V source feeds A through 2 Ω. A has a 4 Ω shunt,a 2 Ω load,and a dependent current source drawing 0.5VA amperes from A.',parts:['Write KCL and solve A.','Find all four branch currents.','Compute the 8 V source power and verify absorption across all other elements.'],givens:'8 V via 2 Ω; shunts 4 Ω and 2 Ω; dependent transconductance 0.5 S.',unknowns:'Node voltage,branch currents,and complete power balance.',answer:'A=16/7=2.285714 V. Feed current=20/7=2.857143 A; 4 Ω current=4/7 A; 2 Ω current=8/7 A; dependent current=8/7 A. The 8 V source delivers 160/7=22.857143 W.',readAloud:'Four currents leave A:through the input resistor,the two shunts,and the dependent source. Solve for A,then use each element voltage and current for power.',symbols:'A=VA; dependent current is 0.5A amperes; source power delivered is 8Ifeed.',steps:[S('Write dependent-node KCL','(A-8)/2+A/4+A/2+0.5A=0','The dependent source remains active and contributes the final term.'),S('Clear denominators and solve','2A-16+A+2A+2A=0\\Rightarrow7A=16\\Rightarrow A=16/7\\ \\mathrm{V}','Multiplying by four gives a direct one-unknown equation.'),S('Recover branch currents','I_{feed}=20/7\\ \\mathrm{A},\\quad I_4=4/7\\ \\mathrm{A},\\quad I_2=8/7\\ \\mathrm{A},\\quad I_{dep}=8/7\\ \\mathrm{A}','The three passive and dependent load currents sum to the feed current.'),S('Audit all power terms','P_{del}=8(20/7)=160/7\\ \\mathrm{W};\\quad P_R=800/49+64/49+128/49\\ \\mathrm{W},\\quad P_{dep}=128/49\\ \\mathrm{W}','The four absorbed terms total 1120/49=160/7 W,matching the independent source.')],verification:'KCL gives 20/7=4/7+8/7+8/7 A,and absorbed power equals delivered power exactly.',trap:'The dependent current is 0.5VA,not a fixed 0.5 A,and its absorbed power uses terminal A.',marks:[['Correct KCL including the dependent term',5],['Correct node voltage and manual algebra',5],['All branch currents with units',5],['Complete independent-source and absorption power audit',5]]}),
O({id:'LONG-05',kind:'long',difficulty:'Exam',topic:'Dependent-source gain',title:'Find voltage gain and verify a dependent loop',time:16,prompt:'An input vs drives a series loop with R1=2 Ω,R2=4 Ω,and a dependent voltage source 2vx opposing current. The controlling voltage vx is the R2 drop.',parts:['Write KVL and the controlling equation.','Find loop current,vx,and dimensionless gain vx/vs.','For vs=14 V,verify all voltages and the power balance.'],givens:'R1=2 Ω,R2=4 Ω,vdep=2vx,vx=4i.',unknowns:'Current,gain,element voltages,and power at vs=14 V.',answer:'i=vs/14; vx=(2/7)vs; gain=2/7. At vs=14 V,i=1 A,vx=4 V,vdep=8 V,R1 drop=2 V. Source delivers 14 W and the three absorbing elements total 14 W.',readAloud:'The controlling voltage is four i,so the dependent source voltage is eight i. Add all three drops and divide output voltage by input voltage.',symbols:'i is loop current;Gv=vx/vs is dimensionless;vdep=2vx.',steps:[S('Write KVL and control','v_s=2i+4i+2v_x,\\qquad v_x=4i','The dependent source is retained and expressed through the controlling resistor current.'),S('Solve current and output','v_s=14i\\Rightarrow i=v_s/14,\\qquad v_x=4v_s/14=(2/7)v_s','Substitution produces a single proportional relationship.'),S('Evaluate gain and numerical voltages','G_v=2/7;\\qquad v_s=14\\Rightarrow i=1\\ \\mathrm{A},\\ v_x=4\\ \\mathrm{V},\\ v_{dep}=8\\ \\mathrm{V}','The R1 drop is 2 V,so 2+4+8=14 V.'),S('Verify power at the operating point','P_{source,del}=14(1)=14\\ \\mathrm{W};\\quad P_{abs}=1^2(2)+1^2(4)+8(1)=14\\ \\mathrm{W}','The dependent source absorbs 8 W because current enters its positive-drop terminal.')],verification:'Gain is independent of input magnitude,and the 14 V operating point satisfies both KVL and energy conservation.',trap:'Do not deactivate the dependent source or report gain in volts.',marks:[['Correct KVL and controlling relation',5],['Correct current and output expressions',5],['Correct dimensionless gain and numerical values',5],['Operating-point voltage and power verification',5]]}),
O({id:'LONG-06',kind:'long',difficulty:'Exam',topic:'Superposition and complete power roles',title:'Separate source responses then audit total power',time:20,prompt:'Node A connects to 10 V through 5 Ω,to ground through 10 Ω,and receives 2 A upward from an independent current source.',parts:['Use superposition to find both contributions to A and the total.','Find total resistor currents and independent-source currents.','Compute all element powers and explain why power superposition is not used.'],givens:'10 V via 5 Ω; 10 Ω shunt; 2 A injected into A.',unknowns:'Source components,total currents,and power roles.',answer:'VA′=VA″=20/3 V,VA=40/3 V. Feed-branch current=2/3 A from A toward the 10 V source; shunt current=4/3 A down. The 10 V source absorbs 20/3 W,the current source delivers 80/3 W,and resistors absorb 20/9+160/9=20 W.',readAloud:'Each independent source produces twenty thirds volts at A. Add those voltages before finding currents and power. Power uses total quantities,not component-wise squares.',symbols:'VA=VA′+VA″; Ifeed=(10−VA)/5; Pabs=VI with current entering positive terminals.',steps:[S('Compute source-only voltage responses','V_A\\prime=10(10)/(5+10)=20/3\\ \\mathrm{V},\\qquad V_A\\prime\\prime=2(5\\parallel10)=20/3\\ \\mathrm{V}','Open the current source for one case and short only the ideal voltage source for the other.'),S('Add and recover total currents','V_A=40/3\\ \\mathrm{V};\\qquad I_{A\rightarrow10V}=(40/3-10)/5=2/3\\ \\mathrm{A},\\quad I_{10}=4/3\\ \\mathrm{A}','The node voltage exceeds 10 V, so 2/3 A physically flows from A into the positive terminal of the voltage source.'),S('Compute independent-source powers','P_{10V,abs}=10(2/3)=20/3\\ \\mathrm{W},\\qquad P_{2A,del}=(40/3)(2)=80/3\\ \\mathrm{W}','The voltage source absorbs because current enters its positive terminal; the current source delivers because its 2 A leaves positive node A.'),
S('Balance resistor absorption','P_5=(10/3)^2/5=20/9\\ \\mathrm{W},\\quad P_{10}=(40/3)^2/10=160/9\\ \\mathrm{W};\\quad P_R=20\\ \\mathrm{W}','Current-source delivery of 80/3 W equals 20 W of resistor absorption plus 20/3 W absorbed by the voltage source.')],verification:'Total KCL is 2/3+4/3=2 A at A,and the power terms balance exactly without adding source-only powers.',trap:'Deactivate only independent sources during superposition and compute power only after adding responses.',marks:[['Correct two source-only voltage responses',5],['Correct total voltage and branch currents',5],['Correct independent-source power roles',5],['Resistor power balance and nonlinear-power explanation',5]]}),
O({id:'LONG-07',kind:'long',difficulty:'Exam',topic:'Source transformation and power audit',title:'Combine practical sources then verify the original circuit',time:18,prompt:'A 36 V source in series with 6 Ω feeds node A. A 3 Ω shunt connects A to ground,and a 2 A source draws current downward from A.',parts:['Transform the voltage-source branch and combine it with the current source.','Find A and all original branch currents.','Compute source powers and resistor dissipation;verify conservation.'],givens:'36 V via 6 Ω; 3 Ω shunt; 2 A drawn from A.',unknowns:'Norton equivalent,node voltage,currents,and power balance.',answer:'Combined Norton source=4 A upward with 2 Ω; A=8 V. Feed current=14/3 A toward A; shunt current=8/3 A down. The 36 V source delivers 168 W,the 2 A source absorbs 16 W,and resistors absorb 392/3+64/3=152 W.',readAloud:'Thirty-six volts through six ohms becomes six amps upward. Subtract the downward two amps to get four amps net,then multiply by six parallel three ohms.',symbols:'IN=6−2=4 A; RN=6∥3=2 Ω; A=INRN.',steps:[S('Transform and combine sources','I_N=36/6-2=4\\ \\mathrm{A}\\ \\text{upward},\\qquad R_N=6\\parallel3=2\\ \\Omega','The voltage-source resistance moves to parallel and signed Norton currents add.'),S('Solve terminal voltage','A=I_NR_N=4(2)=8\\ \\mathrm{V}','The reduced source drives the equivalent 2 Ω resistance.'),S('Recover original currents','I_{feed}=(36-8)/6=14/3\\ \\mathrm{A},\\qquad I_3=8/3\\ \\mathrm{A}','At A,14/3 A entering equals 8/3 A plus 2 A leaving.'),S('Audit all power terms','P_{36,del}=36(14/3)=168\\ \\mathrm{W};\\quad P_{2A,abs}=8(2)=16\\ \\mathrm{W};\\quad P_R=28(14/3)+8(8/3)=152\\ \\mathrm{W}','The 168 W delivered equals 16 W absorbed by the current source plus 152 W in resistors.')],verification:'Original KCL and total power both balance exactly;the transformed open-circuit voltage is also 4×2=8 V.',trap:'Subtract the downward source current before multiplying by equivalent resistance.',marks:[['Correct Norton transformation and source combination',5],['Correct terminal voltage and original currents',5],['Correct independent-source power roles',5],['Complete resistor and total power audit',5]]}),
O({id:'LONG-08',kind:'long',difficulty:'Challenge',topic:'Meter loading design',title:'Compare meters and design a loading specification',time:20,prompt:'A one-port has VTh=60 V and RTh=5 kΩ. Three meters are available:ideal infinite resistance,20 kΩ,and 100 kΩ.',parts:['Find the reading and current for each meter.','Find each percentage reduction from VTh.','Determine the minimum meter resistance for no more than 1% loading error.'],givens:'VTh=60 V,RTh=5 kΩ; Rm=∞,20 kΩ,100 kΩ; target error≤1%.',unknowns:'Three operating points,errors,and design resistance.',answer:'Ideal:60 V,0 A,0%. 20 kΩ:48 V,2.4 mA,20% error. 100 kΩ:57.142857 V,0.571429 mA,4.761905% error. For≤1% error,Rm≥495 kΩ.',readAloud:'Each finite meter forms a divider with five kilo-ohms. Loading error is R Th divided by R Th plus R m. Require that ratio to be at most zero point zero one.',symbols:'Vm=VThRm/(RTh+Rm); E=RTh/(RTh+Rm).',steps:[S('Evaluate ideal and 20 kΩ cases','V_{\\infty}=60\\ \\mathrm{V};\\qquad V_{20}=60(20/25)=48\\ \\mathrm{V},\\quad I_{20}=60/25=2.4\\ \\mathrm{mA}','An ideal meter draws zero current;the 20 kΩ case draws 2.4 mA.'),S('Evaluate the 100 kΩ case','V_{100}=60(100/105)=57.142857\\ \\mathrm{V},\\qquad I_{100}=60/105=0.571429\\ \\mathrm{mA}','The larger resistance reduces meter current and loading.'),S('Compute all loading errors','E_{20}=5/25=20\\%,\\qquad E_{100}=5/105=4.761905\\%','Error is the fractional difference between open-circuit and loaded voltage.'),S('Solve the design inequality','R_{Th}/(R_{Th}+R_m)\\le0.01\\Rightarrow R_m\\ge99R_{Th}=495\\ \\mathrm{k\\Omega}','At 495 kΩ the reading is 59.4 V,exactly 1% below 60 V.')],verification:'The 20 kΩ and 100 kΩ readings satisfy V=IRm;the boundary meter gives 60×495/500=59.4 V.',trap:'A high-quality meter still loads a high-resistance source;do not assume VTh is always displayed.',marks:[['Correct ideal and 20 kΩ operating points',5],['Correct 100 kΩ operating point',5],['Correct percentage loading errors',5],['Correct 1% design inequality and boundary resistance',5]]}),
O({id:'LONG-09',kind:'long',difficulty:'Challenge',topic:'Unbalanced bridge analysis',title:'Solve an unbalanced bridge without false reduction',time:22,prompt:'A 10 V source feeds a bridge. Left path:5 Ω to A and 20 Ω from A to ground. Right path:10 Ω to B and 10 Ω from B to ground. A 10 Ω bridge resistor joins A and B.',parts:['Write nodal equations at A and B and solve them.','Find bridge current,source current,equivalent resistance,and source power.','Verify KCL,KVL,and power balance.'],givens:'VS=10 V;left 5 Ω and 20 Ω;right 10 Ω and 10 Ω;bridge 10 Ω.',unknowns:'Midpoint voltages and complete input response.',answer:'A=140/19=7.368421 V,B=110/19=5.789474 V,IAB=3/19=0.157895 A from A to B. Source current=18/19=0.947368 A,Req=95/9=10.55556 Ω,source power=180/19=9.473684 W.',readAloud:'The bridge is unbalanced,so A and B differ. Write KCL at both midpoints,including the bridge current with opposite signs.',symbols:'IAB=(A−B)/10; IS=(10−A)/5+(10−B)/10; Req=10/IS.',steps:[S('Write both midpoint balances','(A-10)/5+A/20+(A-B)/10=0,\\qquad(B-10)/10+B/10+(B-A)/10=0','Each equation includes two divider resistors and the cross-branch.'),S('Solve for A and B','A=140/19\\ \\mathrm{V},\\qquad B=110/19\\ \\mathrm{V}','Clearing denominators and eliminating one variable gives the exact nineteenth fractions.'),S('Recover bridge and input quantities','I_{AB}=(A-B)/10=3/19\\ \\mathrm{A};\\quad I_S=10/19+8/19=18/19\\ \\mathrm{A}','Source current is the sum through the two upper resistors.'),S('Compute resistance and power','R_{eq}=10/(18/19)=95/9\\ \\Omega,\\qquad P_S=10(18/19)=180/19\\ \\mathrm{W}','Equivalent resistance uses total terminal current under the 10 V test source.')],verification:'Both midpoint KCL residuals vanish. A−B=30/19 V gives the bridge current,and 10/IS reproduces Req.',trap:'Do not remove the bridge resistor:the divider ratios are unequal and IAB is nonzero.',marks:[['Correct coupled midpoint KCL equations',5],['Correct midpoint voltages and bridge current',5],['Correct source current and equivalent resistance',5],['Correct source power and independent verification',5]]}),
O({id:'LONG-10',kind:'long',difficulty:'Challenge',topic:'Nodal-versus-mesh comparison',title:'Solve one network by both nodal and mesh methods',time:22,prompt:'Node A connects to 18 V through 6 Ω,to 6 V through 3 Ω,and to ground through 6 Ω. Solve first by nodal analysis,then by two clockwise mesh currents.',parts:['Use one nodal equation to find A and all branch currents.','Write and solve the corresponding two-mesh system.','Compute source powers and show both methods give the same energy balance.'],givens:'18 V via 6 Ω; 6 V via 3 Ω; 6 Ω shunt.',unknowns:'Node voltage,mesh currents,branch currents,and source power roles.',answer:'A=7.5 V. Mesh currents:i1=1.75 A,i2=0.5 A; shared current=1.25 A down. The 18 V source delivers 31.5 W; the 6 V source absorbs 3 W; resistor absorption totals 28.5 W.',readAloud:'Nodal analysis needs one KCL equation. Mesh analysis needs two KVL equations and then a mesh-current difference for the shared resistor.',symbols:'i1 is left clockwise current;i2 is right clockwise current;A=6(i1−i2).',steps:[S('Solve by nodal analysis','(A-18)/6+(A-6)/3+A/6=0\\Rightarrow4A=30\\Rightarrow A=7.5\\ \\mathrm{V}','One equation directly gives the common node voltage and then all branch currents.'),S('Write and solve mesh KVL','12i_1-6i_2=18,\\qquad-6i_1+9i_2=-6\\Rightarrow i_1=1.75\\ \\mathrm{A},\\ i_2=0.5\\ \\mathrm{A}','The shared 6 Ω resistor produces coupling;the right source polarity gives the negative RHS.'),S('Compare branch recovery','A=6(i_1-i_2)=6(1.25)=7.5\\ \\mathrm{V}','Both methods give the same shared current and node voltage.'),S('Audit power roles','P_{18,del}=18(1.75)=31.5\\ \\mathrm{W};\\quad P_{6,abs}=6(0.5)=3\\ \\mathrm{W};\\quad P_R=18.375+0.75+9.375=28.5\\ \\mathrm{W}','The 31.5 W delivered equals 28.5 W in resistors plus 3 W absorbed by the 6 V source.')],verification:'Nodal KCL gives −1.75+0.5+1.25=0 A,and mesh substitution satisfies both KVL equations.',trap:'The 6 V source absorbs power because 0.5 A enters its positive terminal.',marks:[['Correct nodal solution and branch currents',5],['Correct mesh equations and currents',5],['Explicit equivalence of both branch recoveries',5],['Correct source powers and total energy balance',5]]}),
O({id:'LONG-11',kind:'long',difficulty:'Challenge',topic:'Superposition with dependent source retained',title:'Separate independent excitations without removing dependence',time:22,prompt:'Node A connects to independent voltage VS through 1 Ω and to ground through 1 Ω. A dependent current source draws VA amperes from A using a 1 S gain. An independent current source IS injects current into A. Take VS=12 V and IS=6 A.',parts:['Derive the scaled node equation and solve the total circuit.','Use superposition for VS-only and IS-only responses while retaining the dependent source.','Find all total currents and powers;show the error caused by deactivating the dependent source.'],givens:'Two 1 Ω resistors; dependent transconductance 1 S; VS=12 V; IS=6 A upward.',unknowns:'Total and component voltages,currents,powers,and dependent-source effect.',answer:'3A=VS+IS;A=6 V. VS-only gives 4 V and IS-only gives 2 V. Feed current=6 A,shunt current=6 A,dependent current=6 A. Voltage source delivers 72 W,current source delivers 36 W,and resistors plus dependent source absorb 108 W. Removing dependence would incorrectly give A=9 V.',readAloud:'KCL is A minus V S plus A plus A equals I S. The dependent current remains A in every subcircuit. Only V S and I S take turns.',symbols:'A=VA; dependent current is 1S×VA; scaled KCL is 3A=VS+IS.',steps:[S('Write and solve total KCL','(A-12)+A+A=6\\Rightarrow3A=18\\Rightarrow A=6\\ \\mathrm{V}','The two resistor currents and dependent current are all retained.'),S('Compute independent-source components','A_{VS}=12/3=4\\ \\mathrm{V},\\qquad A_{IS}=6/3=2\\ \\mathrm{V},\\qquad A=4+2=6\\ \\mathrm{V}','Short VS for the current-only case and open IS for the voltage-only case;the dependent coefficient 3 stays unchanged.'),S('Recover total currents and powers','I_{feed}=I_{shunt}=I_{dep}=6\\ \\mathrm{A};\\quad P_{VS,del}=72\\ \\mathrm{W},\\quad P_{IS,del}=6(6)=36\\ \\mathrm{W}','The current source delivers because its current leaves positive node A;passive and dependent absorption totals 36+36+36=108 W.'),S('Test the invalid deactivation','(A-12)+A=6\\Rightarrow2A=18\\Rightarrow A=9\\ \\mathrm{V}\\ne6\\ \\mathrm{V}','Removing the dependent source changes the conductance and produces the wrong result.')],verification:'Total KCL is 6+6=6+6 A at A,and source delivery 72+36=108 W equals total absorption.',trap:'Dependent sources are not independent excitations and must never be turned off for superposition.',marks:[['Correct total KCL and node voltage',5],['Correct source-only responses with dependence retained',5],['Complete total-current and power audit',5],['Explicit invalid-deactivation comparison',5]]}),
O({id:'LONG-12',kind:'long',difficulty:'Stretch',topic:'Dependent-source design and meter loading',title:'Design a feed resistor then assess meter loading',time:25,prompt:'An 18 V source feeds A through an unknown R. A has a 6 Ω shunt and a dependent current source drawing 0.5VA amperes. Design R so A=3 V,then attach a 3 Ω meter across A.',parts:['Find the design resistance R and all initial branch currents.','Find the loaded node voltage and all loaded currents.','Calculate loading error and verify initial and loaded power balances.'],givens:'VS=18 V; shunt 6 Ω; dependent gain 0.5 S; target A=3 V; meter Rm=3 Ω.',unknowns:'Design R,loaded response,error,and power audits.',answer:'R=7.5 Ω. Initial feed current=2 A,shunt=0.5 A,dependent=1.5 A. Loaded A=36/17=2.117647 V; feed=36/17 A,6 Ω current=6/17 A,meter=12/17 A,dependent=18/17 A. The voltage reduction is 3−36/17=15/17=0.882353 V, or 29.411765%.',readAloud:'At the design point,the shunt and dependent source draw two amps total,so the feed resistor must carry two amps while dropping fifteen volts. With the meter,the six-ohm and three-ohm paths combine to two ohms.',symbols:'R=(18−3)/2; loaded KCL is (A−18)/7.5+A/2+0.5A=0.',steps:[S('Solve the design current and resistance','I_{load}=3/6+0.5(3)=2\\ \\mathrm{A},\\qquad R=(18-3)/2=7.5\\ \\Omega','The feed current supplies both the shunt and dependent source at the target voltage.'),S('Solve the loaded node','(A-18)/7.5+A/6+A/3+0.5A=0\\Rightarrow(A-18)/7.5+A=0\\Rightarrow A=36/17\\ \\mathrm{V}','The 6 Ω and 3 Ω resistor currents sum to A/2,which combines with the dependent A/2.'),S('Recover loaded currents and error','I_{feed}=36/17\\ \\mathrm{A},\\ I_6=6/17\\ \\mathrm{A},\\ I_m=12/17\\ \\mathrm{A},\\ I_{dep}=18/17\\ \\mathrm{A};\\quad E=(3-36/17)/3=5/17=29.411765\\%','All loaded load currents sum to the feed current;error compares loaded voltage with the 3 V design target.'),
S('Audit both power balances','P_{initial,del}=18(2)=36\\ \\mathrm{W}=P_R+P_{dep};\\qquad P_{loaded,del}=18(36/17)=648/17\\ \\mathrm{W}','Initially the feed resistor absorbs 30 W, the shunt 1.5 W, and the dependent source 4.5 W, totaling 36 W. After loading, the feed resistor, 6 Ω shunt, meter, and dependent source absorb 9720/289, 216/289, 432/289, and 648/289 W respectively, totaling 648/17 W.')],verification:'Initial KCL is 2=0.5+1.5 A and loaded KCL is 36/17=6/17+12/17+18/17 A. Initial power is exactly 36 W delivered and absorbed.',trap:'The 3 Ω meter is a real additional load;it changes A and every current rather than merely displaying the design value.',marks:[['Correct design current and feed resistance',5],['Correct loaded node voltage and branch currents',5],['Correct loading-error calculation',5],['Complete initial and loaded power verification',5]]})
];})();

